{{
  (() => {
    const decodeHtml = (str) => {
      const entidades = {
        '&aacute;':'á','&eacute;':'é','&iacute;':'í','&oacute;':'ó','&uacute;':'ú',
        '&Aacute;':'Á','&Eacute;':'É','&Iacute;':'Í','&Oacute;':'Ó','&Uacute;':'Ú',
        '&ntilde;':'ñ','&Ntilde;':'Ñ',
        '&uuml;':'ü','&Uuml;':'Ü',
        '&iexcl;':'¡','&iquest;':'¿',
        '&nbsp;':' ','&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&#39;':"'",
        '&ccedil;':'ç','&Ccedil;':'Ç',
        '&ordm;':'º','&ordf;':'ª'
      };
      let out = str;
      for (const [entidad, caracter] of Object.entries(entidades)) {
        out = out.split(entidad).join(caracter);
      }
      // Entidades numéricas tipo &#241; o &#xF1;
      out = out.replace(/&#(\d+);/g, (m, num) => String.fromCharCode(num));
      out = out.replace(/&#x([0-9a-fA-F]+);/g, (m, hex) => String.fromCharCode(parseInt(hex, 16)));
      return out;
    };

    const doc = new jspdf.jsPDF();
    let y = 15;
    doc.setFontSize(14);
    doc.text("Comentarios - Convocatoria " + appsmith.store.convocatoriaSeleccionada, 10, y);
    y += 10;
    doc.setFontSize(10);

    const preguntasExcluidas = [
      "Observaciones y comentarios sobre los aspectos técnicos de la Plataforma",
      "Observaciones y Comentarios sobre el Coordinador"
    ];

    comentariosCurso.data.forEach((item) => {
      const pregunta = decodeHtml(item.pregunta.replace(/<[^>]*>/g, '')).trim();
      const comentario = decodeHtml(item.comentario.replace(/<[^>]*>/g, ''));

      const excluye = pregunta.includes("aspectos técnicos de la Plataforma") || 
                       pregunta.includes("Comentarios sobre el Coordinador");
      if (excluye) return;

      if (y > 270) { doc.addPage(); y = 15; }

      doc.setFont(undefined, 'bold');
      const preguntaLines = doc.splitTextToSize(pregunta, 180);
      doc.text(preguntaLines, 10, y);
      y += preguntaLines.length * 5 + 2;

      doc.setFont(undefined, 'normal');
      const comentarioLines = doc.splitTextToSize(comentario, 180);
      doc.text(comentarioLines, 10, y);
      y += comentarioLines.length * 5 + 8;
    });

    const pdfDataUri = doc.output('datauristring');
    download(pdfDataUri, "comentarios_convocatoria_" + appsmith.store.convocatoriaSeleccionada + ".pdf", "application/pdf");
  })()
}}
